(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-0201","batch":"05","category":"Categoria B","question":"În ce situație se reține permisul de conducere?","answers":["Atunci când nu se respectă obligația de reducere a vitezei","Atunci când nu se respectă normele referitoare la prioritatea de trecere a pietonilor","Atunci când se încalcă normele legale referitoare la staționare"],"correctIndices":[1],"correct":1,"explanation":"Nereducerea vitezei în cazurile prevăzute de regulament se sancționează cu amenda contravențională prevăzută în clasa a III-a de sancțiuni. Pentru această faptă nu se suspendă dreptul de a conduce, caz în care nu se aplică nici măsura de reținere a permisului de conducere. Neacordarea priorității de trecere pietonilor angajați în traversarea regulamentară a drumului public, atunci când aceștia au prioritate de trecere, se consideră contravenție și se sancționează cu amenda contravențională din clasa a III-a de sancțiuni și cu aplicarea măsurii de reținere a permisului de conducere în vederea suspendării dreptului de a conduce pentru o perioadă de 60 de zile. Staționarea neregulamentară se sancționează cu amenda contravențională prevăzută în clasa a II-a de sancțiuni și cu aplicarea punctelor de penalizare, numărul punctelor de penalizare variind în funcție de regula care s-a încălcat. Pentru această faptă nu se suspendă dreptul de a conduce, caz în care nu se aplică nici măsura de reținere a permisului de conducere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0201.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0201.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 201; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 200 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-situatie-se-retine-permisul-de-conducere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"200","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0202","batch":"05","category":"Categoria B","question":"Ce culoare pot avea lămpile cu lumină intermitentă din spatele autovehiculului / tractorului agricol sau forestier?","answers":["Roșie sau albă","Roșie sau galbenă","Galbenă sau albă"],"correctIndices":[1],"correct":1,"explanation":"Lampile cu lumină intermitentă din spatele autovehiculului / tractorului agricol sau forestier pot fi de culoare galbenă sau roșie. Vehiculele europene sunt dotate de regulă cu lumină intermitentă de culoare galbenă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0202.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0202.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 202; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 201 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-culoare-pot-avea-lampile-cu-lumina-intermitenta-din-spatele-autovehiculului-tractorului-agricol-sau-forestier","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"201","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0203","batch":"05","category":"Categoria B","question":"Imobilizarea unei fracturi fără atele se face cu:","answers":["O folie de material plastic","Eșarfe și triunghiuri de pânză","Carton rigid"],"correctIndices":[1],"correct":1,"explanation":"Imobilizarea unei fracturi (de exemplu la mâini și picioare) se face prin fixarea cu atele a două articulații învecinate fracturii, mai sus și mai jos de locul fracturii. Sub atelă se aplică bandaj moale de tifon (sau vată) pentru prevenirea lezării țesuturilor moi. În cazul în care nu se dispune de atele, imobilizarea se poate face cu eșarfe sau triunghiuri de pânză. Osul fracturat se așază pe bucata de pânză, în poziție cât mai dreaptă, iar colțurile materialului se înnoadă pentru a putea fi suspendat. De exemplu, antebrațul se pune pe bucata de pânză iar colturile înnodate se trec in jurul gâtului pentru a susține mâna în poziție orizontală. O folie de material plastic, de regulă, nu are o rezistență bună, poate fi prea elastică, nu va lăsa pielea să respire si poate apărea transpirația. ATÉLĂ, atele, = Piesă (din lemn, carton sau metal) folosită pentru a imobiliza în mod provizoriu membrele fracturate. Prin urmare, folosind carton rigid ați confecționa o atelă, iar întrebarea se referă la situația în care nu se folosesc atelele.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0203.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0203.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 203; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 202 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/imobilizarea-unei-fracturi-fara-atele-se-face-cu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"202","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0204","batch":"05","category":"Categoria B","question":"Care dintre vehicule trebuie să oprească la semnalul polițistului?","answers":["Toate vehiculele","Tramvaiele și autoturismul","Bicicleta"],"correctIndices":[1],"correct":1,"explanation":"Intersecția este dirijată cu polițist de circulație, în acest caz se va respecta cu prioritate semnalul polițistului. Semnalul adresat de polițist semnifică oprire pentru vehiculele a căror direcție inițială de deplasare se intersectează cu brațele acestuia, în situația dată trebuie să oprească tramvaiele și autoturismul, bicicleta își poate continua deplasarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0204.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0204.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 204; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semaforizată, văzută de sus, dirijată de un polițist rutier. Polițistul cu brațele întinse lateral indică oprirea pentru vehiculele care vin din față și din spate. În intersecție se află un autoturism albastru, aflat în spatele polițistului, un tramvai galben tot în spatele său, un tramvai roșu în fața polițistului și o motocicletă, care vine din lateralul polițistului. Toate vehiculele, mai puțin tramvaiul galben care intenționează să vireze la dreapta, vor să meargă înainte.","needsImageReview":true,"source":"RoDrive · ID 203 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-vehicule-trebuie-sa-opreasca-la-semnalul-politistului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"203","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_212.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0205","batch":"05","category":"Categoria B","question":"Care este traseul de urmat pentru autoturismul din imagine?","answers":["Traseul 1","Traseul 2","Oricare dintre cele două, dacă respectă toate prevederile legii"],"correctIndices":[2],"correct":2,"explanation":"În această intersecție circulația se desfășoară în sens giratoriu iar autovehiculul vine de pe un drum cu o singură bandă de circulație pe sens. Trebuie știut că legislația rutieră nu specifică ce bandă de circulație să se folosească în interiorul unei intersecții cu sens giratoriu. Prin urmare, conducătorul de vehicul poate folosi ambele trasee, atât timp cât respectă prevederile legale cu privire la circulația pe benzi și având obligația să semnalizeze din timp părăsirea intersecției și să se asigure că o pot face fără să perturbe circulația sau să pună în pericol siguranța celorlalți participanți la trafic.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0205.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0205.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 205; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție giratorie. Vehiculul roșu intenționează să iasă pe a treia ieșire. Sensul giratoriu are trei benzi, dar autovehiculul dorește să folosească fie banda din marginea sensului giratoriu(prima bandă), fie banda din mijloc(a doua bandă).","needsImageReview":true,"source":"RoDrive · ID 204 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-traseul-de-urmat-pentru-autoturismul-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"204","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_213.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0206","batch":"05","category":"Categoria B","question":"Un autoturism este prevăzut cu centuri de siguranță pentru toate locurile. Ce persoane sunt obligate să le folosească?","answers":["Persoanele de pe scaunele din spate","Toate persoanele","Persoanele de pe scaunele din față"],"correctIndices":[1],"correct":1,"explanation":"Conducătorii de autovehicule și persoanele care ocupă locuri prevăzute prin construcție cu centuri sau dispozitive de siguranță omologate trebuie să le poarte în timpul circulației pe drumurile publice, cu excepția cazurilor prevăzute în regulament.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0206.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0206.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 206; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 205 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/un-autoturism-este-prevazut-cu-centuri-de-siguranta-pentru-toate-locurile-ce-persoane-sunt-obligate-sa-le-foloseasca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"205","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0207","batch":"05","category":"Categoria B","question":"Oprirea voluntară este interzisă:","answers":["La mai puțin de 50 m de colțul intersecției","În locul în care se împiedică vizibilitatea unui semnal luminos","În curbe cu vizibilitatea sub 100 m"],"correctIndices":[1],"correct":1,"explanation":"Este permisă oprirea la mai puțin de 50 de metri de colțul unei intersecții, deoarece oprirea se interzice în zona de preselecție unde sunt aplicate marcaje continue, iar în lipsa acestora la mai puțin de 25 de metri de colțul intersecției. Oprirea voluntară a vehiculelor este interzisă în locurile unde s-ar împiedica observarea unui indicator sau semnal luminos. Oprirea este interzisă în curbele cu vizibilitatea sub 50 de metri, nu în curbele cu vizibilitate sub 100 de metri.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0207.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0207.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 207; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 206 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/oprirea-voluntara-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"206","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0208","batch":"05","category":"Categoria B","question":"În situația dată sunteți obligat:","answers":["Să nu depășiți viteza de 30 km/h între orele 7.00-22.00, fiind într-o zonă frecventată de copii","Să acordați prioritate de trecere bicicliștilor","Să ocoliți locurile de joacă pentru copii"],"correctIndices":[0],"correct":0,"explanation":"În această situație întâlniți indicatorul \"Copii\", acesta se instalează în apropierea locurilor frecventate de copii (școli, grădinițe, locuri de joacă, parcuri, etc.) acolo unde există posibilitatea ca aceștia să apară pe neașteptate pe partea carosabilă. La întâlnirea acestuia trebuie să circulați cu atenție sporită iar în intervalul orar 7:00 - 22:00, aveți obligația să reduceți viteza până la 30 km/h în localități și 50 km/h în afara localităților.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0208.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0208.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 208; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o stradă urbană din perspectiva unui șofer, cu vehicule parcate pe partea dreaptă și indicatorul triunghiular cu margini roșii, cu doi copii în mijlocul său, avertizând faptul că este o zonă frecventată de copii.","needsImageReview":true,"source":"RoDrive · ID 207 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-situatia-data-sunteti-obligat","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"207","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_215.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0209","batch":"05","category":"Categoria B","question":"Cum trebuie să procedați în situația dată?","answers":["Vă continuați deplasarea, deoarece cele două lumini roșii alternante indică permisiunea de a traversa calea ferată","Opriți","Vă continuați deplasarea dacă semibarierele nu sunt coborâte încă"],"correctIndices":[1],"correct":1,"explanation":"În situația dată observăm că semnalul cu lumini intermitent-alternative roșii este în funcțiune, acest semnal obligă conducătorii de vehicule să oprească, urmând ca barierele să coboare. În situația dată trebuie să opriți autovehiculul în fața barierei și să așteptați semnalul care vă permite trecerea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0209.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0209.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 209; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere la nivel cu calea ferată din perspectiva unui șofer, semnalizată cu semnale luminoase și bariere. Barierele sunt coborâte, dar semnalele luminoase intermitent-alternative roșii sunt pornite. Șoferul se află în fața trecerii și intenționează să treacă.","needsImageReview":true,"source":"RoDrive · ID 208 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedati-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"208","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_216.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0210","batch":"05","category":"Categoria B","question":"Care dintre cele trei autoturisme este parcat regulamentar?","answers":["Autoturismul albastru","Autoturismul roșu și autoturismul albastru, deoarece nu depășesc zona marcată de indicator","Autoturismul verde și autoturismul roșu, deoarece respectă semnificația indicatorului"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul împreună cu panoul adițional confirmă o zonă special amenajată pentru parcare, unde vehiculele vor parca paralel cu drumul și cu toate roțile pe trotuar. Dintre cele trei autoturisme, doar autoturismul verde și cel roșu au parcat regulamentar, autoturismul albastru nu a respectat semnificația indicatorului și a panoului adițional parcând doar cu două roți pe trotuar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0210.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0210.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 210; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicator dreptunghiular albastru, cu inscripția P albă și o mașină albă care se află pe o porțiune mai înaltă de drum în interiorul său, care semnifică faptul că este permisă parcarea paralelă cu drumul pe trotuar. Sub indicator se află un panou adițional dreptunghiular, cu o săgeată care are capăt atât în sus, cât și în jos, ceea ce indică faptul că șoferii pot să parcheze înainte și în spatele indicatorii, cât timp respectă regulile impuse de indicator.","needsImageReview":true,"source":"RoDrive · ID 209 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-cele-trei-autoturisme-este-parcat-regulamentar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"209","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_217.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0211","batch":"05","category":"Categoria B","question":"Dacă la trecerea la nivel cu calea ferată constatați că un vehicul este imobilizat pe calea ferată, cum veți proceda?","answers":["Vă continuați drumul, deoarece degajarea căii ferate se va face de către personalul calificat","Opriți și anunțați telefonic poliția despre acest incident","Acordați sprijin pentru scoaterea vehiculului de pe calea ferată sau, dacă nu este posibil, semnalați prezența acestuia"],"correctIndices":[2],"correct":2,"explanation":"Dacă la trecerea la nivel cu calea ferată constatați că un vehicul este imobilizat pe calea ferată, sunteți obligat să acordați sprijin pentru scoaterea vehiculului de pe calea ferată, iar dacă acest lucru nu este posibil, semnalați prezența vehiculului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0211.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0211.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 211; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 210 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/daca-la-trecerea-la-nivel-cu-calea-ferata-constatati-ca-un-vehicul-este-imobilizat-pe-calea-ferata-cum-veti-proceda","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"210","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0212","batch":"05","category":"Categoria B","question":"În care dintre situații este interzisă schimbarea direcției de mers spre stânga?","answers":["Când conducătorul de vehicul este încadrat pe banda din dreapta","Când drumul pe care urmează să se intre este semnalizat cu indicatorul „circulația interzisă în ambele sensuri”","Când strada pe care urmează să se intre este semnalizată cu indicatorul „drum fără ieșire”"],"correctIndices":[0,1],"correct":0,"explanation":"Schimbarea direcției de mers spre stânga nu se efectuează atunci când v-ați încadrat pe banda din dreapta, deoarece efectuând manevra din această poziție se îngreunează buna desfășurare a circulației rutiere. Schimbarea direcției de mers spre stânga nu se efectuează în situația în care drumul pe care doriți să intrați, la stânga, este semnalizat cu indicatorul „Circulația interzisă în ambele sensuri”. Acest indicator interzice circulația în ambele sensuri a tuturor vehiculelor. Indicatorul „Drum fără ieșire” NU vă interzice să intrați pe acea stradă, dar vă informează că respectivul drum este fără ieșire. Prin urmare, vă este permisă schimbarea direcției de mers spre stânga atunci când strada pe care urmează să intrați este semnalizată cu indicatorul „Drum fără ieșire”.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0212.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0212.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 212; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 211 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatii-este-interzisa-schimbarea-directiei-de-mers-spre-stanga","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"211","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0213","batch":"05","category":"Categoria B","question":"Puteți lăsa noaptea, pe un drum public, remorca autovehiculului / tractorului agricol sau forestier?","answers":["Nu, întrucât în acest caz staționarea este interzisă","Da, deoarece remorca nu face parte din categoria autovehiculelor","Da, dacă luminile de poziție sunt aprinse"],"correctIndices":[0],"correct":0,"explanation":"Legislația rutieră interzice staționarea remorcilor pe timpul nopții pe partea carosabilă a drumurilor publice.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0213.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0213.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 213; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 212 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/puteti-lasa-noaptea-pe-un-drum-public-remorca-autovehiculului-tractorului-agricol-sau-forestier","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"212","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0214","batch":"05","category":"Categoria B","question":"Ce rol au tetierele, din punct de vedere al conduitei preventive?","answers":["În cazul tamponării din spate a autovehiculului, previn posibila fracturare a coloanei cervicale","Nu au decât rol estetic","Contribuie la fixarea telefoanelor mobile, permițând efectuarea convorbirilor fără a mai duce aparatul la ureche"],"correctIndices":[0],"correct":0,"explanation":"În afară de rolul de susținere a capului/gâtului pasagerilor, ce are ca efect diminuarea stresului acumulat în zona cervicală a coloanei, din punct de vedere al conduitei preventive, tetierele au rolul de a preveni posibila fracturare a coloanei cervicale în cazul lovirii din spate a autovehiculului, prin susținerea capului și nelăsarea acestuia să se deplaseze către înapoi (față de restul corpului, din cauza inerției) în timpul tamponării.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0214.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0214.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 214; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 213 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-rol-au-tetierele-din-punct-de-vedere-al-conduitei-preventive","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"213","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0215","batch":"05","category":"Categoria B","question":"Ce obligații îi revin conducătorului auto când constată, noaptea, că lumina farurilor nu se mai aprinde?","answers":["Să folosească luminile de poziție până ajunge într-un loc de parcare unde poate remedia defecțiunea","Să asigure funcționarea cel puțin a luminii de întâlnire din stânga a vehiculului și a unei lumini de poziție din spate","Să circule cu atenție până la primul service auto"],"correctIndices":[1],"correct":1,"explanation":"În situația în care constatați, pe timp de noapte, că autovehiculul pe care îl conduceți are defecțiuni la sistemul de iluminare astfel încât lumina farurilor nu se mai aprinde, trebuie să încetați conducerea acestuia. Iar pentru al putea conduce pe timpul nopții sau în condiții de vizibilitate redusă, aveți obligația să asigurați funcționarea pe partea stânga, în față o lumină de întâlnire și în spate una de poziție.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0215.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0215.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 215; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 214 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-ii-revin-conducatorului-auto-cand-constata-noaptea-ca-lumina-farurilor-nu-se-mai-aprinde","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"214","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0216","batch":"05","category":"Categoria B","question":"Puteți depăși tramvaiul oprit în stație?","answers":["Nu, deoarece tramvaiul se depășește prin partea stângă","Nu, deoarece în stație nu există refugiu pentru pietoni","Da, deoarece între șina de tramvai și trotuar există spațiu suficient pentru depășire"],"correctIndices":[1],"correct":1,"explanation":"Atunci când întâlniți un tramvai oprit într-o stație fără refugiu pentru pietoni, aveți obligația de a opri în spatele tramvaiului, acordând prioritate pietonilor care traversează strada și vă puteți relua deplasarea numai după ce ușile tramvaiului au fost închise și v-ați asigurat că nu puneți în pericol siguranța pietonilor angajați în traversarea drumului public. Depășirea vehiculelor se interzice în dreptul stației pentru tramvai, atunci când acesta este oprit, iar stația nu este prevăzută cu refugiu pentru pietoni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0216.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0216.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 216; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un tramvai staționat pe partea stângă a drumului, din perspectiva unui șofer aflat pe partea dreaptă a drumului. Tramvaiul a staționat în dreptul unei stații fără refugiu pentru pietoni, permițând unui pieton să coboare în stație.","needsImageReview":true,"source":"RoDrive · ID 215 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/puteti-depasi-tramvaiul-oprit-in-statie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"215","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_223.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0217","batch":"05","category":"Categoria B","question":"Ce obligații aveți atunci când intrați pe autostradă folosind banda de accelerare?","answers":["Să cedați trecerea autovehiculelor care circulă pe prima bandă a autostrăzii și să nu stânjeniți în niciun fel circulația acestora","Să semnalizați stânga, pentru a-i preveni pe ceilalți conducători să vă acorde prioritate","Să opriți și să vă asigurați din față și din spate"],"correctIndices":[0],"correct":0,"explanation":"Atunci când doriți să intrați pe autostradă folosind banda de accelerare, aveți obligația de a ceda trecerea autovehiculelor care circulă pe prima bandă a autostrăzii și să nu stânjeniți în niciun fel circulația acestora. La folosirea benzii de accelerare pe autostradă se va semnaliza stânga, dar NU pentru a-i preveni pe ceilalți conducători să vă acorde prioritate, ci pentru că este obligatorie semnalizarea schimbării direcției de mers sau trecerea pe o altă bandă de circulație. Nu este obligatorie oprirea pentru asigurare atunci când intrați pe autostradă folosind banda de accelerare. La intrarea pe o bandă de accelerare se întâlnește instalat indicatorul „Cedează trecerea”, care NU obligă la oprire, dar care obligă la cedarea trecerii vehiculelor care circulă pe autostradă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0217.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0217.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 217; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 216 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-atunci-cand-intrati-pe-autostrada-folosind-banda-de-accelerare","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"216","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0218","batch":"05","category":"Categoria B","question":"Dacă circulați pe un drum național european (E), vă este interzis:","answers":["Să folosiți pe timpul zilei luminile de întâlnire","Să opriți pe partea carosabilă","Să depășiți"],"correctIndices":[1],"correct":1,"explanation":"Nu vă este interzissă folosiți pe timpul zilei luminile de întâlnire pe un drum național european (E). Mai mult de atât, legislația rutieră îi obligă pe conducătorii de autovehicule și tractoare agricole sau forestiere, atunci când circulă pe orice categorie de drum public, să foloseascăși în timpul zilei luminile de întâlnire sau luminile pentru circulația diurnă. Atunci când circulați pe un drum Național European (E),vă este interzisă oprirea voluntară pe partea carosabilă. Pe această categorie de drum vă sunt interzise și manevrele de staționare, întoarcere și mers înapoi. Manevra de depășire nu va este interzisă pe drumurile Naționale Europene (E).","imageUrl":"/nivel-1/quiz-images/rodrive-all/0218.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0218.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 218; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 217 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/daca-circulati-pe-un-drum-national-european-e-va-este-interzis","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"217","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0219","batch":"05","category":"Categoria B","question":"Exercitarea dreptului de a conduce se suspendă pe o perioadă de 30 de zile pentru:","answers":["Nerespectarea regulilor referitoare la remorcare","Utilizarea excesivă a claxonului","Depășirea unei coloane de vehicule oprite la culoarea roșie a semaforului"],"correctIndices":[2],"correct":2,"explanation":"Nerespectarea regulilor privind remorcarea vehiculelor se sancționează doar cu amenda prevăzută în clasa a IV-a de sancțiuni. Pentru această faptă NU se suspendă dreptul de a conduce. Utilizarea excesivă a claxonului, mai exact nerespectarea regulilor de utilizare a mijloacelor de avertizare sonoră, se sancționează doar cu amenda prevăzută în clasa a II-a de sancțiuni. Pentru această faptă NU se suspendă dreptul de a conduce. Este interzisă depășirea unei coloane de vehicule aflată în așteptare la culoarea roșie a semaforului, această contravenție se sancționează cu amenda prevăzută în clasa a II-a de sancțiuni și cususpendarea exercitării dreptului de a conduce pentru o perioadă de 30 de zile.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0219.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0219.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 219; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 218 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/exercitarea-dreptului-de-a-conduce-se-suspenda-pe-o-perioada-de-30-de-zile-pentru","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"218","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0220","batch":"05","category":"Categoria B","question":"Indicatorul semnifică:","answers":["Accesul interzis vehiculelor cu o înălțime mai mare de 3,5 m","Accesul permis numai vehiculelor cu o lățime mai mică de 3,5 m","Distanța minimă obligatorie dintre două vehicule"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul pe care l-ați întâlnit se numește “Accesul interzis vehiculelor cu înălțimea mai mare de 3.5 metri”. Acest indicator interzice accesul vehiculelor care au o înălțime mai mare de 3.5 metri. De exemplu, dacă un autocamion are o înălțime de până la 3.5 metri îi este permis accesul, dacă înălțimea acestuia depășea 3.5 metri accesul îi era interzis.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0220.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0220.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 220; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un pod cu înălțime limitată, din perspectiva unui șofer în trafic, aflat în fața acelui pod. Un indicator circular, cu margini roșii, cu câte un triunghi negru în partea de sus, respectiv partea de jos a indictorului, cu vârfurile spre mijlocul acestuia, cu inscripția '3,50 m', este prezent, care interzice circulația vehiculelor cu o înălțime mai mare de 3,50 metri","needsImageReview":true,"source":"RoDrive · ID 219 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"219","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_227.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0221","batch":"05","category":"Categoria B","question":"În ce ordine vor trece autovehiculele prin intersecția prezentată?","answers":["Roșu, verde albastru","Verde, roșu, albastru","Albastru, verde, roșu"],"correctIndices":[1],"correct":1,"explanation":"Intersecția este dirijată cu indicatoare de reglementare de prioritate, autovehiculul roșu și cel albastru întâlnesc indicatorul „Cedează trecerea” și au obligația de a ceda trecerea autovehiculului verde, în acest caz autovehiculul verde trece primul, deoarece se afla pe drumul cu prioritate. Între autovehiculul roșu și cel albastru s-a creat o situație de egalitate, situație în care se va aplica regula priorității de dreapta, autovehiculul albastru, virând către stânga, are obligația de a-i acorda prioritate autovehiculului roșu deoarece acesta îi vine din partea dreaptă. Ordinea de trecere va fi următoarea: autovehiculul verde, urmat de autovehiculul roșu, iar ultimul va trece autovehiculul albastru.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0221.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0221.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 221; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție nesemaforizată, văzută de sus. Un autoturism albastru, aflat în dreapta, intenționează să vireze la stânga. Un autoturism roșu, aflat la dreapta și un autoturism verde, aflat jos, intenționează să meargă înainte. Autoturismul albastru și autoturismul roșu au în dreptul lor un indicator triunghiular, cu margini roșii, care le impune să cedeze trecerea celorlalte vehicule.","needsImageReview":true,"source":"RoDrive · ID 220 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-ordine-vor-trece-autovehiculele-prin-intersectia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"220","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_228.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0222","batch":"05","category":"Categoria B","question":"Exercitarea dreptului de a conduce se suspendă pe o perioadă de 60 de zile pentru:","answers":["Circulația pe sens opus, cu excepția cazurilor în care se efectuează regulamentar manevra de depășire","Depășirea cu cel mult 30 km/h a vitezei maxime admise","Cumul de 10 puncte de penalizare"],"correctIndices":[0],"correct":0,"explanation":"Se interzice circulația pe sensul opus, cu excepția cazurilor în care se efectuează regulamentar manevra de depășire. Nerespectarea acestei interziceri se sancționează cu suspendarea dreptului de a conduce pentru o perioada de 60 de zile. Pentru depășirea cu cel mult 30 km/h a vitezei maxime admise se aplică amendă contravențională și puncte de penalizare. Nu se sancționează și cu suspendarea dreptului de a conduce. Depășirea limitei maxime de viteză este interzisă, iar sancțiunile aplicate variază în funcție de valoarea cu care aceasta a fost depășită. De exemplu, dacă se circulă pe un sector de drum pe care viteza maximă admisă este de 50 km/h și se depășește această limită maximă admisă cu o viteză cuprinsă între 10 și 50 de km/h (viteza cu care se circulă fiind cuprinsă între 60 și 100 de km/h) se va sancționa cu amendă contravențională și puncte de penalizare. Iar dacă se depășește această limită maximă admisă cu o viteză cuprinsă între 50 și 70 de km/h (viteza cu care se circulă fiind între 100 și 120 de km/h), se va sancționa cu amendă contravențională și cu aplicarea măsurii de reținere a permisului de conducere în vedereasuspendării dreptului de a conduce pentru o perioadă de 90 de zile. Însă dacă se depășește această limită maximă admisă cu mai mult de 70 de km/h (viteza cu care se circulă fiind peste 120 de km/h), se va sancționa cu amendă contravențională și cu aplicarea măsurii de reținere a permisului de conducere în vedereasuspendării dreptului de a conduce pentru o perioadă de 120 de zile. Prin urmare, varianta B de răspuns nu poate fi corectă pentru că în c","imageUrl":"/nivel-1/quiz-images/rodrive-all/0222.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0222.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 222; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 221 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/exercitarea-dreptului-de-a-conduce-se-suspenda-pe-o-perioada-de-60-de-zile-pentru","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"221","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0223","batch":"05","category":"Categoria B","question":"Pentru care dintre faptele de mai jos se aplică puncte de penalizare?","answers":["Pentru conducerea vehiculului de către o altă persoană decât proprietarul","Pentru conducerea vehiculului fără una dintre plăcuțele cu numărul de înmatriculare","Noxele motorului ating limita legală admisă"],"correctIndices":[1],"correct":1,"explanation":"Se poate conduce un vehicul de către o altă persoană decât proprietarul, dar cu acordul proprietarului. Prin urmare, acest lucru nefiind interzis nu se va sancționa cu puncte de penalizare sau cu aplicarea unei alte sancțiuni. Trebuie știut că la solicitarea poliției rutiere sau a poliției locale, proprietarul sau deținătorul mandatat al unui vehicul este obligat să comunice acesteia, în termenul indicat în cuprinsul solicitării, datele de identificare ale persoanei căreia i-a încredințat vehiculul pentru a-l conduce pe drumurile publice. Nerespectarea acestei obligații constituie contravenție și se sancționează cu amenda prevăzută în clasa a IV-a de sancțiuni. Conducerea pe drumurile publice a unui vehicul fără a avea montată una dintre plăcuțele cu numărul de înmatriculare sau de înregistrare constituie contravenție și se sancționează cu amenda prevăzută în clasa a IV-a de sancțiuni, cu aplicarea a 6 puncte de penalizare și cu reținerea certificatului de înmatriculare sau de înregistrare, eliberând-se o dovadă înlocuitoare cu drept de circulație pentru 15 zile. Dacă noxele emanate de motoratinglimita legal admisă,deci nu o depășesc, se poate circula cu autovehiculul. Dacă acest lucru nu este interzis, deoarece noxele emanate de motor NU depășesc limita legal admisă, nu se va sancționa cu puncte de penalizare sau cu aplicarea unei alte sancțiuni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0223.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0223.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 223; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 222 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pentru-care-dintre-faptele-de-mai-jos-se-aplica-puncte-de-penalizare","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"222","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0224","batch":"05","category":"Categoria B","question":"Ce semnifică indicatorul?","answers":["Interzice circulația în ambele sensuri a autovehiculelor","Interzice circulația în ambele sensuri a motocicletelor și motoretelor","Interzice circulația în ambele sensuri a tuturor vehiculelor"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul se numește “Accesul interzis în ambele sensuri”, acest indicator se instalează pe drumurile care nu sunt deschise circulației publice și interzice circulația tuturor vehiculelor în ambele sensuri. Acestui indicator i se poate atașa si un panou adițional pe care se precizează categoriile de autovehicule care fac excepție de la această interzicere sau un panou adițional cu inscripția „Cu excepția riveranilor”.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0224.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0224.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 224; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum care nu este deschis circulației publice, cu indicatorul circular cu margini roșii, cu fundal alb, care interzice accesul tuturor vehiculelor în ambele sensuri 'Acces interzis'.","needsImageReview":true,"source":"RoDrive · ID 223 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnifica-indicatorul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"223","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_231.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0225","batch":"05","category":"Categoria B","question":"Principala cauză a exploziei pneului în timpul mersului este:","answers":["Umflarea insuficientă","Umflarea exagerată","Uzura moderată"],"correctIndices":[1],"correct":1,"explanation":"Dacă pneul are o presiune insuficientă, anvelopa se deformează permanent, se încălzește excesiv, se uzează pe marginile suprafeței de rulare și apar crăpături în șanțurile profilului. În timp poate duce la explozia pneului, dar nu este principala cauză. Un pneu umflat exagerat este foarte vulnerabil în timpul mersului. Datorită presiunii mari, a loviturilor, a forțelor centrifuge, precum și a temperaturii, armătura acestuia poate ceda și pneul va exploda. Prin urmare, principala cauză a exploziei pneului în timpul mersului este umflarea exagerată. O uzură moderată a pneurilor nu prezintă pericol de explozie, mai ales dacă pneul este utilizat corespunzător. Presiunea recomandată este indicată pe interiorul clapetei rezervorului de combustibil, pe banda interioara a portierei din partea șoferului, în manualul autovehiculului, sau în compartimentul motorului. Există două valori de presiune recomandate, una pentru cazul în care mașina este încărcată la greutatea maximă sau pe autostradă și alta pentru călătoriile cu încărcarea la greutatea normală.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0225.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0225.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 225; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un vehicul staționat pe partea dreaptă a drumului, alături de doi oameni care efectuează reparații.","needsImageReview":true,"source":"RoDrive · ID 224 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/principala-cauza-a-exploziei-pneului-in-timpul-mersului-este","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"224","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_232.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0226","batch":"05","category":"Categoria B","question":"Pentru a folosi telefonul mobil, atunci când nu aveți un sistem de tip „mâini libere“:","answers":["Opriți pe banda de staționare","Opriți în parcarea din zona complexului de servicii","Telefonul poate fi folosit fără restricții"],"correctIndices":[1],"correct":1,"explanation":"Conducătorilor de vehicule le este interzis ca în timpul conducerii să utilizeze telefoane mobile, acestea pot fi folosite doar dacă sunt dotate cu dispozitive de tip “mâini libere”. Prin urmare, în lipsa dispozitivelor de tip “mâini libere”, pentru folosirea telefonului mobil este nevoie să opriți autovehiculul. Oprirea pe banda de staționare (denumirea corectă este banda de urgență) a autostrăzilor fiind interzisă (excepție făcând cazurile de urgență, justificate), trebuie să opriți în parcarea din zona complexului de servicii care urmează.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0226.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0226.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 226; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum expres cu indicatorul dreptunghiular verde, pe care scrie 'Spațiu servicii' cu alb în partea de sus și '3000 m' metri în partea de jos, indicând faptul că în 3000 de metri va apărea un spațiu de servicii. În mijlocul său sunt mai multe chenare albe, alături de un chenar albastru pe care scrie P cu alb, indicând faptul că spațiul de servicii conține o parcare.","needsImageReview":true,"source":"RoDrive · ID 225 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pentru-a-folosi-telefonul-mobil-atunci-cand-nu-aveti-un-sistem-de-tip-maini-libere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"225","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_233.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0227","batch":"05","category":"Categoria B","question":"În ce ordine trec prin intersecția prezentată cele trei autovehicule?","answers":["Albastru, roșu, verde","Albastru, verde, roșu","Roșu, albastru, verde"],"correctIndices":[1],"correct":1,"explanation":"Această intersecție este dirijată cu indicatoare de reglementare de prioritate, sub fiecare indicator se găsește instalat un panou adițional care indică direcția drumului cu prioritate. Linia îngroșată indică direcția drumului cu prioritate. Pe drumul cu prioritate circulă autovehiculul albastru și are prioritate de trecere față de cele două autovehicule care întâlnesc indicatorul „Cedează trecerea”, deci primul va trece autovehiculul albastru. Între autovehiculul verde și cel roșu s-a creat o situație de egalitate, ambele întâlnind indicatorul „Cedează trecerea”, situație în care se va aplica regula priorității de dreapta. Autovehiculul roșu îi va ceda trecerea autovehiculului verde deoarece acesta îi vine din partea dreaptă. Ordinea de trecere este următoarea: autovehiculul albastru, urmat de autovehiculul verde, iar ultimul prin intersecție va trece autovehiculul roșu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0227.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0227.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 227; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea reprezintă o intersecție nesemaforizată, văzută de sus, cu trei autoturisme de culori diferite (verde, roșu, și albastru). Drumurile de jos și din stânga au un indicator de prioritate romboidal, cu margine albă și fundal galben, iar drumurile de sus și din dreapta au un indicator triunghiular cu margini roșii, care le indică să cedeze trecerea. Toate indicatoarele au sub câte un panou adițional care arată configurația intersecției și direcția drumului prioritar, adică că drumul care începe de jos și continuă spre stânga . Drumul prioritar urmează o curbă în stânga jos. Autoturismul verde, aflat în partea de sus a imaginii, intenționează să meargă înainte. Autoturismul roșu, aflat în dreapta, semnalizează intenția de a vira la stânga. Autoturismul albastru, aflat jos, semnalizează intenția de a vira la stânga.","needsImageReview":true,"source":"RoDrive · ID 226 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-ordine-trec-prin-intersectia-prezentata-cele-trei-autovehicule","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"226","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_234.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0228","batch":"05","category":"Categoria B","question":"În care dintre următoarele situații sunteți obligat să circulați cu o viteză care să nu depășească 30 km/h în localități?","answers":["La trecerile la nivel cu linia de tramvai","La trecerile la nivel cu calea ferată industrială","Când partea carosabilă este acoperită cu mâzgă"],"correctIndices":[2],"correct":2,"explanation":"Nu aveți obligația de a circula cu o viteză care să nu depășească 30 km/h în localități la trecerea la nivel cu linia de tramvai. Legislația rutieră nu obligă să se circule cu o viteză care să nu depășească 30 km/h în localități la trecerile la nivel cu calea ferată industrială, dar prevede obligația de a vă conforma semnificației semnalelor agenților de cale ferată care dirijează circulația la trecerile la nivel cu calea ferată industrială. Legislația rutieră vă obligă să circulați cu o viteză care să nu depășească 30 km/h în localități sau 50 km/h în afara localităților atunci când partea carosabilă este acoperită cu polei, gheață, zăpadă bătătorită, mâzgă sau piatră cubică umedă. În aceste situații riscul de a se produce accidente de circulație este foarte mare iar respectarea regimului legal de viteză și adaptarea acesteia în funcție de condițiile de drum ajută la evitarea eventualelor accidente de circulație.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0228.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0228.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 228; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 227 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-urmatoarele-situatii-sunteti-obligat-sa-circulati-cu-o-viteza-care-sa-nu-depaseasca-30-km-h-in-localitati","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"227","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0229","batch":"05","category":"Categoria B","question":"Întoarcerea este interzisă:","answers":["Pe drumurile cu circulație intensă","Când există riscul ca marginea drumului să cedeze, respectiv soliditatea drumului nu permite","Pe poduri"],"correctIndices":[1,2],"correct":1,"explanation":"Pe drumurile pe care circulația este intensă NU se interzice manevra de întoarcere a vehiculului. Însă, având în vedere că pentru efectuarea acestei manevre aveți obligația de a vă asigura că nu circulă în acel moment niciun vehicul, trebuie să țineți cont că în aceste locuri este necesar să aveți mai multă răbdare și o atenție sporită pentru asigurare, mai ales dacă este necesară manevrarea înainte și înapoi a vehiculului. Legislația rutieră interzice întoarcerea vehiculului în locurile unde soliditatea drumului nu permite, de exemplu într-un loc unde marginea drumului nu este solidă și poate să cedeze. Legislația rutieră interzice întoarcerea vehiculului în locurile în care este interzisă oprirea vehiculelor, dar cu excepția intersecțiilor. Prin urmare, pe poduri se interzice întoarcerea vehiculului, deoarece în aceste locuri este interzisă oprirea vehiculelor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0229.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0229.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 229; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 228 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intoarcerea-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"228","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0230","batch":"05","category":"Categoria B","question":"Care dintre faptele de mai jos constituie infracțiune și se pedepsește ca atare?","answers":["Conducerea pe drumul public a unui autovehicul neînmatriculat","Conducerea pe drumul public a unui autovehicul fără certificat de înmatriculare","Conducerea pe drumul public a unui autovehicul cu număr de înmatriculare fals"],"correctIndices":[0,2],"correct":0,"explanation":"Este interzisă conducerea pe drumul public a unui autovehicul neînmatriculat. Această faptăconstituie infracțiuneși se pedepsește cu închisoare de la unu la 3 ani sau cu amendă. Conducerea pe drumul public a unui autovehicul fără certificat de înmatriculare, adică fără a avea asupra dvs. certificatul de înmatriculare,constituie contravenție. Pentru această faptă se aplică amenda contravențională prevăzută în clasa a III-a de sancțiuni. Este interzisă conducerea pe drumul public a unui autovehicul cu număr de înmatriculare fals. Această faptăconstituie infracțiuneși se pedepsește cu închisoare de la unu la 5 ani sau cu amendă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0230.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0230.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 230; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 229 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-faptele-de-mai-jos-constituie-infractiune-si-se-pedepseste-ca-atare","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"229","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0231","batch":"05","category":"Categoria B","question":"Circulați într-o coloană și respectați distanța față de vehiculul din față. Ce trebuie să faceți în plus?","answers":["Să aprindeți lanterna de ceață din spate","Să observați prin geamul lateral al vehiculului marginea din dreapta a părții carosabile","Să rămâneți la limita propriei benzi și să vă asigurați câmpul de vizibilitate"],"correctIndices":[2],"correct":2,"explanation":"Luminile de ceață se vor folosi, împreună cu luminile de întâlnire, doar pe timp de ceață densă iar în situația din întrebare nu se specifică dacă este sau nu ceață. Prin urmare, este interzis să aprindeți lanterna de ceață din spate, pentru nerespectarea acestei reguli se va aplica amendă contravențională și puncte de penalizare. Observarea marginii din dreapta a părții carosabile se face și se reglează prin parbriz, nu prin geamul lateral al vehiculului. În timpul deplasării, vehiculele trebuie să păstreze o distanță suficientă față de marginea din dreapta a drumului, față de vehiculele pe lângă care circulă, în același sens sau în sens opus și față de vehiculul din față. În cazul în care vehiculele circulă într-o coloană, conducătorul de vehicul trebuie pe lângă aceste măsuri să rămână pe propria bandă și să își asigure câmpul de vizibilitate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0231.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0231.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 231; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 230 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/circulati-intr-o-coloana-si-respectati-distanta-fata-de-vehiculul-din-fata-ce-trebuie-sa-faceti-in-plus","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"230","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0232","batch":"05","category":"Categoria B","question":"Când sunteți obligat să opriți vehiculul?","answers":["La semnalele îndrumătorilor de circulație ai ministerului apărării","La semnalele conducătorilor de vehicule care virează la dreapta","La semnalele conducătorilor vehiculelor care circulă din sens invers"],"correctIndices":[0],"correct":0,"explanation":"Pe lângă obligația de a opri la semnalele polițistului rutier, participanții la trafic sunt obligați să oprească și la semnalele îndrumătorilor de circulație ai Ministerului Apărării. Aceștia din urmă pot efectua, pe lângă semnalele de oprire, și următoarele semnale: balansarea brațului în plan vertical, cu palma mâinii orientată către sol sau cu un mijloc de semnalizare, care semnifică reducerea vitezei, precum și rotirea vioaie a brațului, care semnifică mărirea vitezei de deplasare a vehiculelor, inclusiv grăbirea traversării drumului de către pietoni. Nerespectarea acestor semnale se sancționează cu amendă prevăzută în clasa a II-a de sancțiuni. Nu este obligatorie oprirea la semnalele conducătorilor de vehicule care virează la dreapta sau ale conducătorilor vehiculelor care circulă din sens invers.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0232.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0232.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 232; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 231 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cand-sunteti-obligat-sa-opriti-vehiculul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"231","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0233","batch":"05","category":"Categoria B","question":"Un autovehicul avariat nu mai poate circula dacă:","answers":["Are elemente de caroserie distruse","Au trecut mai mult de 30 de zile de la data producerii avariei","Au trecut mai mult de 3 zile de la constatare"],"correctIndices":[1],"correct":1,"explanation":"Dacă autovehiculul avariat are elemente de caroserie distruse, dar starea tehnică este bună, acesta poate circula pe drumurile publice, dar nu mai mult de 30 de zile de la data producerii avariei. Conducătorului de autovehicul îi este interzis să circule cu autovehiculul avariat mai mult de 30 de zile de la data producerii avariei. Conducătorii de vehicule implicați într-un accident de circulație în urma căruia au rezultat numai avarierea vehiculelor și/sau alte pagube materiale sunt obligați să se prezinte la unitatea de poliție competentă pe raza căreia s-a produs accidentul în termen de cel mult 24 de ore de la producerea evenimentului pentru întocmirea documentelor de constatare. Se exceptează de la această obligație cei care fac o constatare amiabilă de accident sau ceai care au o asigurare facultativă de avarii auto, iar accidentul de circulație a avut ca rezultat numai avarierea propriului vehicul. Data producerii avariei se regăsește în constatarea făcută de către poliția rutieră sau, după caz, în polița de constatare amiabilă. Dacă au trecut mai mult de 3 zile de la constatarea accidentului, autovehiculul avariat poate circula dacă starea tehnică este bună, dar nu mai mult de 30 de zile de la data producerii avariei.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0233.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0233.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 233; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 232 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/un-autovehicul-avariat-nu-mai-poate-circula-daca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"232","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0234","batch":"05","category":"Categoria B","question":"În cazul unui accident cu victime și cu deformarea accentuată a caroseriei, procedați la:","answers":["Victimele conștiente sunt sfătuite să nu se miște, iar degajarea acestora trebuie să se realizeze cât mai repede și numai de către echipaje specializate","Degajarea victimelor trebuie să se realizeze cât mai repede, prin orice mijloace","Se administrează calmante victimelor care sunt conștiente"],"correctIndices":[0],"correct":0,"explanation":"În cazul unui accident cu victime și cu deformarea accentuată a caroseriei, victimele conștiente sunt sfătuite să nu se miște, deoarece este posibil să aibă fracturi de coloană iar mișcarea lor ar putea să le provoace paralizia sau chiar moartea. Degajarea acestora trebuie să se realizeze cât mai repede și numai de către echipaje specializate. Degajarea victimelor trebuie să se realizeze numai de către echipaje specializate și prim mijloace de specialitate pentru a nu agrava starea victimelor. Nu se administrează calmante sau alte medicamente victimelor, acest lucru se face doar de către echipajele specializate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0234.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0234.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 234; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 233 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-cazul-unui-accident-cu-victime-si-cu-deformarea-accentuata-a-caroseriei-procedati-la","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"233","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0235","batch":"05","category":"Categoria B","question":"Ce vă este interzis în această situație?","answers":["Să opriți sau să staționați","Să depășiți alte vehicule, cu excepția bicicletelor sau a căruțelor","Să călcați marcajul aplicat pe carosabil"],"correctIndices":[0],"correct":0,"explanation":"În această situație întâlniți indicatorul “Drum îngustat pe partea stângă”, la întâlnirea acestui indicator manevrele de oprire, staționare, mers înapoi și întoarcere sunt interzise pe porțiunea de drum îngustat. Manevra de depășire este permisă. Manevra de depășire nu se interzice pe acest sector de drum. Nu se interzice încălcarea marcajului deoarece acesta este cu linie discontinuă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0235.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0235.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 235; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o situație din perspectiva unui șofer, pe un drum urban cu indicatorul triunghiular cu margini roșii, având o linie dreaptă verticală în dreapta sa și o linie verticală care se frânge în mijloc, ce avertizează faptul că drumul va fi îngustat pe partea stângă. Șoferul se află pe partea stângă. Drumul are și marcaj transversal cu linie discontinuă.","needsImageReview":true,"source":"RoDrive · ID 234 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-va-este-interzis-in-aceasta-situatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"234","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_242.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0236","batch":"05","category":"Categoria B","question":"Autoturismul din imagine a parcat regulamentar?","answers":["Da, deoarece este parcat în întregime pe trotuar","Nu, deoarece se află în afara zonei în care parcarea este permisă","Da, deoarece respectă atât semnificația indicatorului, cât și a semnului adițional"],"correctIndices":[1],"correct":1,"explanation":"Indicatorul din imagine se numește „Parcare” și permite parcarea vehiculelor, însă desenul de pe acest indicator precizează că acestea vor fi parcate paralel cu drumul și cu toate roțile pe trotuar, iar panoul adițional instalat sub indicator precizează începutul zonei unde parcarea este permisă. Autoturismul a respectat indicațiile înscrise pe indicator, parcând cu toate roțile pe trotuar dar nu a respectat semnificația panoului adițional și a parcat în afara zonei în care parcarea este permisă, deci a parcat neregulamentar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0236.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0236.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 236; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicator dreptunghiular albastru, pe care scrie cu alb P și are un desen cu o mașină aflată deasupra unei linii albe, care indică faptul că parcarea este permisă, cât timp mașina este parcată paralel cu drumul și cu toate roțile pe trotuar. Sub el se află un panou adițional, dreptunghiular, cu o săgeată neagră îndreptată în sus, care arată faptul că zona de parcare începe după indicator. O mașină este parcată, înaintea indicatorului, cu roțile pe trotuar și paralel cu drumul.","needsImageReview":true,"source":"RoDrive · ID 235 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/autoturismul-din-imagine-a-parcat-regulamentar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"235","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_243.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0237","batch":"05","category":"Categoria B","question":"Polițistul din intersecție semnalizează conducătorul auto să mărească viteza. Cum trebuie să procedeze acesta?","answers":["Să respecte semnalul polițistului","Să aștepte lumina verde a semaforului","Să acorde prioritate, apoi să își continue deplasarea"],"correctIndices":[0],"correct":0,"explanation":"Semnalele, indicațiile și dispozițiile polițistului rutier se vor respecta cu prioritate, indiferent de situație. Polițistul rutier adresează un semnal de mărire a vitezei iar conducătorul autoturismului este obligat să respecte semnificația semnalului adresat de acesta și să mărească viteza de deplasare, chiar dacă semaforul indică culoarea roșie.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0237.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0237.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 237; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semaforizată dirijată de un polițist rutier. Un autoturism roșu este situat în fața polițistului. Autoturismul se află în fața unui semafor roșu, dar polițistul își mișcă brațul stâng circular, indicându-i să mărească viteza de deplasare.","needsImageReview":true,"source":"RoDrive · ID 236 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/politistul-din-intersectie-semnalizeaza-conducatorul-auto-sa-mareasca-viteza-cum-trebuie-sa-procedeze-acesta","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"236","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_244.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0238","batch":"05","category":"Categoria B","question":"Ce indică această poziție a polițistului rutier?","answers":["Reduceți viteza","Măriți viteza","Oprire"],"correctIndices":[2],"correct":2,"explanation":"Brațul întins orizontal al polițistului rutier semnifică \"oprire\" pentru toți participanții la trafic care, indiferent de sensul lor de mers, circulă din direcția intersectată de brațul întins, indiferent dacă acesta are sau nu si bastonul reflectorizant. Prin urmare, semnalul polițistului rutier semnifică oprire pentru participanții la trafic care circulă din fața acestuia.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0238.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0238.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 238; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un polițist rutier care are brațul stâng ridicat, ținând în mână un baston reflectorizant, cu culorile alb și roșu, ce indică oprirea vehiculelor care circulă din direcția intersectată de brațul întins.","needsImageReview":true,"source":"RoDrive · ID 237 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-indica-aceasta-pozitie-a-politistului-rutier","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"237","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_245.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0239","batch":"05","category":"Categoria B","question":"Vă este permisă trecerea peste marcajul longitudinal din imagine?","answers":["Da, deoarece linia discontinuă este cea mai apropiată de vehiculul pe care îl conduceți","Nu, deoarece este un marcaj dublu","Nu, deoarece în acest caz depășirea este interzisă"],"correctIndices":[0],"correct":0,"explanation":"În situația de față întâlniți un marcaj format dintr-o linie continuă și una discontinuă, alăturate. Trebuie să respectați semnificația liniei celei mai apropiate în sensul de mers. În această situație linia cea mai apropiată fiind cea discontinuă, linie care permite încălcarea acesteia. Prin urmare, vă este permisă trecerea peste acest marcaj.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0239.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0239.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 239; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o stradă urbană cu mai multe benzi de circulație și vehicule parcate pe marginea drumului, din perspectiva unui șofer. Strada prezintă un marcaj longitudinal, cu linie discontinuă pe sensul de mers al șoferului și cu linie continuă pe sensul opus.","needsImageReview":true,"source":"RoDrive · ID 238 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/va-este-permisa-trecerea-peste-marcajul-longitudinal-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"238","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_246.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0240","batch":"05","category":"Categoria B","question":"Cum trebuie să procedați atunci când intenționați să finalizați o depășire?","answers":["Semnalizați revenirea și efectuați manevra în condiții de siguranță","După reîncadrare, semnalizați cu luminile de avarie","Claxonați și vă angajați pe partea dreaptă, direct în fața vehiculului depășit"],"correctIndices":[0],"correct":0,"explanation":"Atunci când doriți să efectuați manevra de depășire, aveți următoarele obligații:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0240.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0240.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 240; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 239 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedati-atunci-cand-intentionati-sa-finalizati-o-depasire","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"239","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0241","batch":"05","category":"Categoria B","question":"Conducătorul de autovehicul poate efectua depășirea pe partea dreaptă a autovehiculului al cărui conducător a semnalizat intenția schimbării direcției de mers spre stânga?","answers":["Da, dacă vehiculul din față s-a angajat corespunzător părăsirii sensului de mers","Da, dacă s-a creat spațiu suficient pentru această manevră","Nu"],"correctIndices":[0,1],"correct":0,"explanation":"Depășirea se efectuează, de regulă, pe partea stângă a vehiculului depășit, dar în situația în care un vehicul a semnalizat intenția și s-a încadrat corespunzător părăsirii sensului de mers spre stânga, acesta se depășește pe partea dreaptă. Această manevră de depășire pe partea dreaptă se va efectua doar dacă există spațiu suficient pentru această manevră. Trebuie să reținem că nu ne este permisă depășirea dacă nu s-a creat spațiu suficient pentru depășire. De exemplu, nu este permisă depășirea atunci când în lipsa spațiului necesar pentru efectuarea manevrei se circulă pe trotuar, chiar și atunci când vehiculul urcă doar parțial pe trotuar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0241.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0241.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 241; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 240 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducatorul-de-autovehicul-poate-efectua-depasirea-pe-partea-dreapta-a-autovehiculului-al-carui-conducator-a-semnalizat-intentia-schimbarii","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"240","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0242","batch":"05","category":"Categoria B","question":"La intersecția nedirijată dintre un drum național și unul județean, comunal sau local, prioritatea de trecere se acordă:","answers":["Vehiculelor care circulă pe drumul județean, comunal sau local","Vehiculelor care vin din dreapta","Vehiculelor care circulă pe drumul național"],"correctIndices":[2],"correct":2,"explanation":"La intersecțianedirijată a două drumuri de categorii diferitenu se aplică regula priorității de dreapta, se va acorda prioritate vehiculelor care circulă pe „drumul superior”. Regula priorității de dreapta se va aplica în intersecția nedirijată dacă drumurile care se intersectează sunt de aceeași categorie (de exemplu două drumuri comunale sau două străzi dintr-un oraș). Dacă drumurile care se intersectează sunt de categorii diferite se va acorda prioritate vehiculelor care circulă pe „drumul superior”. Prin urmare, atunci când veniți de pe un drum județean, comunal sau local și doriți să pătrundeți pe un drum național, aveți obligația de a acorda prioritate vehiculelor care circulă pe drumul național.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0242.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0242.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 242; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 241 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-intersectia-nedirijata-dintre-un-drum-national-si-unul-judetean-comunal-sau-local-prioritatea-de-trecere-se-acorda","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"241","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0243","batch":"05","category":"Categoria B","question":"Când este permisă trecerea la nivel cu o cale ferată fără bariere, prevăzută cu semnalizare luminoasă, dacă tocmai a trecut un tren?","answers":["După ce s-a stins lumina roșie intermitentă","După ce a trecut ultimul vagon","Atunci când pleacă vehiculele aflate de cealaltă parte a căii ferate"],"correctIndices":[0],"correct":0,"explanation":"Oprirea la trecerea la nivel cu calea ferată fără bariere, prevăzută cu semnalizare luminoasă, se realizează prin funcționarea dispozitivelor cu lumini intermitent-alternative roșii și stingerea semnalizării de control reprezentate de lumină intermitentă albă și, acustic, prin emiterea de semnale sonore intermitente. După trecerea trenului, pentru a putea traversa calea ferată, trebuie să așteptați stingerea luminilor de culoare roșie și aprinderea semnalului cu lumina alba intermitentă cu cadență lentă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0243.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0243.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 243; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 242 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cand-este-permisa-trecerea-la-nivel-cu-o-cale-ferata-fara-bariere-prevazuta-cu-semnalizare-luminoasa-daca-tocmai-a-trecut-un-tren","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"242","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0244","batch":"05","category":"Categoria B","question":"Aveți obligația de a opri imediat vehiculul la semnalele adresate de:","answers":["Membrii patrulelor școlare de circulație, de la trecerile pentru pietoni din apropierea unităților de învățământ","Personalul autorizat din cadrul ministerului transporturilor","Lucrătorii ce își desfășoară activitatea în cadrul administrației drumurilor"],"correctIndices":[0],"correct":0,"explanation":"Pe lângă obligația de a opri la semnalele polițistului rutier, participanții la trafic sunt obligați să oprească și la semnalele membrilor patrulelor școlare de circulație, la trecerile pentru pietoni din apropierea unităților de învățământ. Nerespectarea acestor semnale se sancționează cu amendă prevăzută în clasa a II-a de sancțiuni. Nu este obligatorie oprirea la semnalele date de personalul autorizat din cadrul Ministerului Transporturilor (a nu se confunda cu îndrumătorii de circulație ai Ministerului Apărării​). Nu este obligatorie oprirea la semnalele date de lucrătorii ce își desfășoară activitatea în cadrul Administrației Drumurilor (a nu se confunda cu personalul autorizat din zona lucrărilor pe drumurile publice​).","imageUrl":"/nivel-1/quiz-images/rodrive-all/0244.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0244.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 244; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 243 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/aveti-obligatia-de-a-opri-imediat-vehiculul-la-semnalele-adresate-de","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"243","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0245","batch":"05","category":"Categoria B","question":"Dacă semaforul în funcțiune se află instalat de cealaltă parte a intersecției, conducătorul de vehicul:","answers":["Nu este obligat să respecte semnificația semnalelor luminoase, deoarece nu i se adresează","Este obligat să respecte semnificația semnalelor luminoase, doar dacă semaforul este însoțit de un semn adițional care indică direcțiile cărora li se adresează semnalele","Este obligat să respecte semnificația semnalelor luminoase ale acestuia, dacă un alt semafor instalat la intrarea în intersecție are în funcțiune un semnal similar"],"correctIndices":[2],"correct":2,"explanation":"Semafoarele care emit semnale luminoase pentru dirijarea circulației în intersecțiise instalează obligatoriu înainte de intersecție, astfel încât să fie vizibile de la o distanță de cel puțin 50 metri de intersecție. Acesteapot fi repetateîn mijlocul, deasupra oride cealaltă parte a intersecției. Prin urmare, dacă semaforul este repetat de cealaltă parte a intersecției și are semnalul similar cu cel instalat înaintea intersecției, conducătorul de vehicul va respecta semnificația acestuia. Aceste semafoare repetate în mijlocul, deasupra ori de cealaltă parte a intersecției au rolul de a facilita vizualizarea semnalelor de către toți participanții la trafic cărora li se adresează.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0245.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0245.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 245; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 244 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/daca-semaforul-in-functiune-se-afla-instalat-de-cealalta-parte-a-intersectiei-conducatorul-de-vehicul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"244","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0246","batch":"05","category":"Categoria B","question":"Depășirea nu este permisă:","answers":["Atunci când vehiculul ce urmează a fi depășit rulează cu viteza admisă de lege","În orice locuri și situații în care vizibilitatea nu permite executarea manevrei","Atunci când traficul rutier este aglomerat"],"correctIndices":[1],"correct":1,"explanation":"Atunci când vehiculul ce urmează a fi depășitrulează cu viteza admisă de legeNUînseamnă că acesta rulează cu vitezaMAXIMA ADMISĂde lege, el poate să ruleze cu viteză mai mică decât limita maximă admisă și este considerată o viteză admisă de lege. În plus, trebuie să ținem cont că limitele maxime de viteză sunt diferite în funcție de categoria vehiculului condus. Prin urmare, se poate efectua manevra de depășire dacă nu se depășește limita maximă de viteză admisă de lege, pentru categoria din care face parte vehiculul condus. La efectuarea depășirii trebuie să vă asigurați că manevra se poate efectua în condiții de siguranță. Pentru a respecta această obligație trebuie să aveți vizibilitate. Prin urmare, depășirea nu este permisă în orice locuri și situații în care vizibilitatea nu permite efectuarea manevrei. Atunci când traficul rutier este aglomerat nu se interzice manevra de depășire, dar este important ca manevra să se execute în condiții de siguranță. Trebuie să ținem cont că atunci când prin manevra de depășire se trece peste axa drumului, conducătorul de vehicul trebuie să se asigure că din sens opus nu se apropie un vehicul și că dispune de spațiu suficient pentru a reintra pe banda inițială.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0246.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0246.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 246; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 245 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/depasirea-nu-este-permisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"245","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0247","batch":"05","category":"Categoria B","question":"Întoarcerea vehiculului este interzisă:","answers":["Unde marcajul axial este discontinuu","În intersecțiile unde este necesară manevrarea înainte și înapoi","În zona de acțiune a indicatorului „staționarea interzisă“"],"correctIndices":[1],"correct":1,"explanation":"Marcajul care desparte sensurile de circulație format dintr-o linie discontinuă permite trecerea peste acesta la efectuarea manevrelor. Prin urmare, întoarcerea vehiculelor este permisă unde marcajul axial este discontinuu. Marcajul cu linie continuă este cel care interzice încălcarea și implicit interzice și întoarcerea vehiculelor. Se interzice întoarcerea vehiculelor în intersecțiile în care, pentru efectuarea manevrei, este necesară manevrarea înainte și înapoi a vehiculului. Indicatorul „Staționarea interzisă” nu are rolul de a interziceîntoarcereavehiculelor, acesta interzicestaționareavehiculelor. În zona de acțiune a acestuia nu se interzice șioprireavehiculelor, se interzice doar staționarea vehiculelor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0247.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0247.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 247; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 246 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intoarcerea-vehiculului-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"246","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0248","batch":"05","category":"Categoria B","question":"La ieșirea din zonele rezidențiale sau pietonale, sunteți obligat să acordați prioritate:","answers":["Autovehiculelor","Pietonilor de pe sensul opus de circulație","Tuturor vehiculelor cu care vă intersectați"],"correctIndices":[2],"correct":2,"explanation":"La ieșirea din zonele rezidențiale sau pietonale, sunteți obligat să acordați prioritate de treceretuturor vehiculelor, nu doar autovehiculelor. La ieșirea din zonele rezidențiale sau pietonale, sunteți obligat să acordați prioritate de trecere pietonului care traversează drumul public, prin loc special amenajat, marcat și semnalizat corespunzător ori la culoarea verde a semaforului destinat lui,atunci când acesta se află pe sensul de mers al vehiculului. Dar în varianta B de răspuns nu se specifică dacă pietonul este în afara zonei rezidențiale sau pietonale sau dacă se află în traversare pe o trecere pentru pietoni. Chiar dacă pietonul se află pe o trecere pentru pietoni marcată și semnalizată corespunzător, tot nu aveți obligația să îi acordați prioritate, deoarece acesta este pe sensul opus de circulație, după cum se specifică în varianta de răspuns. Atunci când ieșiți dintr-o zonă pietonală sau rezidențială aveți obligația de a acorda prioritate de treceretuturor vehiculelorcu care vă intersectați. Atenție! Trebuie să acordați prioritate de treceretuturor vehiculelor, chiar și bicicletelor sau trotinetelor electrice.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0248.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0248.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 248; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 247 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-iesirea-din-zonele-rezidentiale-sau-pietonale-sunteti-obligat-sa-acordati-prioritate","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"247","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0249","batch":"05","category":"Categoria B","question":"Precizați în care dintre situații este interzisă staționarea voluntară a vehiculelor?","answers":["În dreptul căilor de acces care deservesc proprietățile alăturate drumurilor publice","În zona aglomerată a piețelor","În pante și în rampe"],"correctIndices":[0,2],"correct":0,"explanation":"Este interzisă staționarea voluntară a vehiculelor în dreptul cailor de acces care deservesc proprietățile alăturate drumurilor publice, precum și în pante și în rampe.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0249.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0249.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 249; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 248 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/precizati-in-care-dintre-situatii-este-interzisa-stationarea-voluntara-a-vehiculelor","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"248","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0250","batch":"05","category":"Categoria B","question":"Ce manevre sunt interzise pe autostradă?","answers":["Oprirea și efectuarea unei pene de cauciuc","Învățarea conducerii unui vehicul","Încercarea prototipurilor de șasiuri și de vehicule cu motor"],"correctIndices":[1,2],"correct":1,"explanation":"Oprirea pentru efectuarea unei pene de cauciuc sau pentru oricare altă situație de urgență este permisă pe banda de urgență. Pe autostradă se interzice învățarea conducerii vehiculelor și încercarea prototipurilor de șasiuri și autovehicule.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0250.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0250.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 250; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 249 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-manevre-sunt-interzise-pe-autostrada","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"249","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
